        private void ExportLeagueWinLossBetTypeDataRow(
            int startColumn,
            int currentRow,
            BettypeWinLossBySite info,
            ExcelWorksheet workSheet,
            bool isTotalRow,
            bool isHedge = false,
            bool isFromBetTypeStatus = false,
            bool isChoice = false)
        {
            var currentColumn = startColumn;
            var currentCell = workSheet.Cells[currentRow, currentColumn];
            if (isTotalRow || isFromBetTypeStatus)
            {
                var hedgeText = isHedge ? " (hedge) " : "";
                currentCell.Value = info.BettypeName + hedgeText;
            }
            else
            {
                currentCell.Value = isChoice ? info.Choice : info.SiteType;
            }

            currentCell.Style = isTotalRow ? subRowTextStyle : textStyle;
            currentCell.Style.HorizontalAlignment = HorizontalAlignmentStyle.Right;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];
            currentCell.Value = info.MemberWinLoss;
            currentCell.Style = isTotalRow ? subRowPositiveTwoDecimalNumberStyle : positiveTwoDecimalNumberStyle;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];
            currentCell.Value = info.SMAWinLoss;
            currentCell.Style = isTotalRow ? subRowTwoDecimalNumberStyle : twoDecimalNumberStyle;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];
            currentCell.Value = info.ExtraPT;
            currentCell.Style = isTotalRow ? subRowTwoDecimalNumberStyle : twoDecimalNumberStyle;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];
            currentCell.Value = info.Commission;
            currentCell.Style = isTotalRow ? subRowTwoDecimalNumberStyle : twoDecimalNumberStyle;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];
            currentCell.Value = info.VarianceIncome;
            currentCell.Style = isTotalRow ? subRowPositiveTwoDecimalNumberStyle : positiveTwoDecimalNumberStyle;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];
            currentCell.Value = info.VirtualWinLoss;
            currentCell.Style = isTotalRow ? subRowPositiveTwoDecimalNumberStyle : positiveTwoDecimalNumberStyle;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];
            currentCell.Value = info.RealIncome;
            currentCell.Style = isTotalRow ? subRowPositiveTwoDecimalNumberStyle : positiveTwoDecimalNumberStyle;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];
            currentCell.Value = info.VirtualTurnover;
            currentCell.Style = isTotalRow ? subRowTwoDecimalNumberStyle : twoDecimalNumberStyle;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];
            currentCell.Value = info.RealTurnover;
            currentCell.Style = isTotalRow ? subRowTwoDecimalNumberStyle : twoDecimalNumberStyle;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];

            if (info.VirtualTurnover != 0)
            {
                currentCell.Value = Converter.ToDecimal(info.VirtualMargin);
            }
            else
            {
                currentCell.Value = Labels.NotAvailable;
            }

            currentCell.Style = isTotalRow ? subRowPositiveTwoDecimalPercentNumberStyle : positiveTwoDecimalPercentNumberStyle;
            currentColumn++;

            currentCell = workSheet.Cells[currentRow, currentColumn];

            if (info.RealTurnover != 0)
            {
                currentCell.Value = Converter.ToDecimal(info.RealMargin);
            }
            else
            {
                currentCell.Value = Labels.NotAvailable;
            }

            currentCell.Style = isTotalRow ? subRowPositiveTwoDecimalPercentNumberStyle : positiveTwoDecimalPercentNumberStyle;
        }

